function drawDoorDecoration(ctx,cx,cy,col,row){var hw=HEX_W*0.35;var hh=HEX_H*0.4;ctx.fillStyle=CT_DARK_WARM;ctx.fillRect(cx-hw-2,cy-hh-1,hw*2+4,hh*2+2);ctx.beginPath();ctx.arc(cx,cy-hh-1,hw+2,Math.PI,0);ctx.fill();ctx.fillStyle=CT_BARK_BROWN;ctx.fillRect(cx-hw,cy-hh,hw*2,hh*2);ctx.beginPath();ctx.arc(cx,cy-hh,hw,Math.PI,0);ctx.fillStyle=CT_BARK_BROWN;ctx.fill();ctx.strokeStyle=CT_BARK_DEEP;ctx.lineWidth=0.6;for(var pi=-1;pi<=1;pi++){ctx.beginPath();ctx.moveTo(cx+pi*hw*0.5,cy-hh);ctx.lineTo(cx+pi*hw*0.5,cy+hh);ctx.stroke();}
ctx.strokeStyle=CT_STONE_DARK;ctx.lineWidth=1.2;ctx.beginPath();ctx.moveTo(cx-hw,cy-hh*0.5);ctx.lineTo(cx+hw,cy-hh*0.5);ctx.stroke();ctx.beginPath();ctx.moveTo(cx-hw,cy+hh*0.5);ctx.lineTo(cx+hw,cy+hh*0.5);ctx.stroke();if(_tileDetail>=1){ctx.fillStyle=CT_STONE_MID;for(var si=-1;si<=1;si+=2){ctx.beginPath();ctx.arc(cx+si*hw*0.6,cy-hh*0.5,1,0,Math.PI*2);ctx.arc(cx+si*hw*0.6,cy+hh*0.5,1,0,Math.PI*2);ctx.fill();}}
ctx.strokeStyle=CT_WARM_BROWN;ctx.lineWidth=1;ctx.beginPath();ctx.arc(cx+hw*0.4,cy+1,2,0,Math.PI*2);ctx.stroke();ctx.fillStyle=CT_STONE_MID;ctx.beginPath();ctx.arc(cx+hw*0.4,cy-1,0.8,0,Math.PI*2);ctx.fill();if(_tileDetail>=2){ctx.fillStyle=CT_BLACK_NEAR;ctx.fillRect(cx+hw*0.38,cy+3,1.5,2);}}
function drawWallEnhanced(ctx,cx,cy,col,row,biome){const seed=col*7+row*13;const hw=HEX_W*0.38;const hh=HEX_H*0.38;ctx.strokeStyle='rgba(0,0,0,0.15)';ctx.lineWidth=0.5;for(let i=0;i<3;i++){const y=cy-hh+(i+1)*hh*0.5;const xOff=(i%2===0)?0:hw*0.4;ctx.beginPath();ctx.moveTo(cx-hw+xOff,y);ctx.lineTo(cx+hw-(hw*0.4-xOff),y);ctx.stroke();}
if((seed%10)<3){ctx.strokeStyle='rgba(0,0,0,0.25)';ctx.lineWidth=0.6;const crackX=cx+((seed%5)-2)*hw*0.3;const crackY=cy+((seed%7)-3)*hh*0.2;ctx.beginPath();ctx.moveTo(crackX,crackY-hh*0.3);ctx.lineTo(crackX+hw*0.1,crackY);ctx.lineTo(crackX-hw*0.05,crackY+hh*0.25);ctx.stroke();}
if(biome==='cave'||biome==='graveyard'){if((seed%10)>=6&&(seed%10)<8){ctx.fillStyle='rgba(40,80,30,0.3)';const mx=cx+((seed%3)-1)*hw*0.5;const my=cy+hh*0.3;ctx.beginPath();ctx.arc(mx,my,HEX_W*0.06,0,Math.PI*2);ctx.fill();ctx.beginPath();ctx.arc(mx+hw*0.15,my-hh*0.1,HEX_W*0.04,0,Math.PI*2);ctx.fill();}}}
function drawTorchOnWall(ctx,cx,cy,timestamp){ctx.strokeStyle=CT_WOOD_MID;ctx.lineWidth=1.5;ctx.beginPath();ctx.moveTo(cx,cy-HEX_H*0.15);ctx.lineTo(cx,cy-HEX_H*0.3);ctx.stroke();var flicker=Math.sin(timestamp*0.008+cx*0.5)*0.15+0.85;var flameH=HEX_H*0.2*flicker;if(_tileDetail>=1){var grad=ctx.createRadialGradient(cx,cy-HEX_H*0.35,0,cx,cy-HEX_H*0.35,HEX_W*0.12);grad.addColorStop(0,'rgba(255,200,50,'+(0.9*flicker)+')');grad.addColorStop(0.5,'rgba(255,120,20,'+(0.6*flicker)+')');grad.addColorStop(1,'rgba(255,60,10,0)');ctx.fillStyle=grad;}else{ctx.fillStyle='rgba(255,160,30,'+(0.7*flicker).toFixed(3)+')';}
ctx.beginPath();ctx.ellipse(cx,cy-HEX_H*0.35,HEX_W*0.08,flameH,0,0,Math.PI*2);ctx.fill();if(_tileDetail>=1){var glowGrad=ctx.createRadialGradient(cx,cy-HEX_H*0.3,0,cx,cy-HEX_H*0.3,HEX_W*0.5);glowGrad.addColorStop(0,'rgba(255,180,50,'+(0.15*flicker)+')');glowGrad.addColorStop(1,'rgba(255,180,50,0)');ctx.fillStyle=glowGrad;ctx.beginPath();ctx.arc(cx,cy-HEX_H*0.3,HEX_W*0.5,0,Math.PI*2);ctx.fill();}}
function drawTrapMark(ctx,cx,cy,col,row){const s=HEX_W*0.15;ctx.strokeStyle='rgba(120,80,40,0.25)';ctx.lineWidth=0.5;ctx.setLineDash([2,2]);ctx.strokeRect(cx-s,cy-s*0.6,s*2,s*1.2);ctx.setLineDash([]);ctx.fillStyle='rgba(120,80,40,0.2)';ctx.beginPath();ctx.arc(cx,cy,HEX_W*0.03,0,Math.PI*2);ctx.fill();}
function drawSecretWallHint(ctx,cx,cy){ctx.strokeStyle='rgba(60,40,20,0.3)';ctx.lineWidth=0.7;ctx.setLineDash([1,3]);const hw=HEX_W*0.2;ctx.beginPath();ctx.moveTo(cx-hw,cy-HEX_H*0.1);ctx.lineTo(cx,cy+HEX_H*0.05);ctx.lineTo(cx+hw*0.5,cy-HEX_H*0.15);ctx.stroke();ctx.setLineDash([]);}
function drawWallTileDecoration(ctx,cx,cy,col,row,biome){const seed=(col*7+row*13)%100;ctx.strokeStyle='rgba(0,0,0,0.2)';ctx.lineWidth=0.5;if(seed%3===0){ctx.beginPath();ctx.moveTo(cx-4,cy-2);ctx.lineTo(cx-1,cy+1);ctx.lineTo(cx+3,cy-1);ctx.stroke();}
if(seed%5<2){ctx.beginPath();ctx.moveTo(cx+2,cy+3);ctx.lineTo(cx+5,cy+1);ctx.stroke();}
if(biome==='cave'||biome==='graveyard'){if(seed%4===0){ctx.fillStyle='rgba(40,80,30,0.15)';ctx.beginPath();ctx.arc(cx-3,cy+4,2,0,Math.PI*2);ctx.fill();}
if(seed%7<2){ctx.fillStyle='rgba(50,90,40,0.12)';ctx.beginPath();ctx.arc(cx+4,cy-2,1.5,0,Math.PI*2);ctx.fill();}}
ctx.fillStyle='rgba(0,0,0,0.08)';for(let i=0;i<3;i++){const dx=((seed+i*17)%12)-6;const dy=((seed+i*23)%10)-5;ctx.fillRect(cx+dx,cy+dy,1,1);}}
function drawChestDecoration(ctx,cx,cy,col,row,timestamp){const t=(timestamp||0)*0.001;const pulse=0.3+Math.sin(t*1.5)*0.1;ctx.fillStyle='rgba(0,0,0,0.2)';ctx.beginPath();ctx.ellipse(cx+1,cy+2,7,3,0,0,Math.PI*2);ctx.fill();ctx.fillStyle=CT_BARK_BROWN;ctx.fillRect(cx-5,cy-4,10,7);ctx.fillStyle=CT_WOOD_LIGHT;ctx.fillRect(cx-6,cy-7,12,4);ctx.fillStyle=CT_WOOD_TAN;ctx.fillRect(cx-5,cy-8,10,2);ctx.fillStyle=CT_GOLD;ctx.fillRect(cx-6,cy-4,12,1);ctx.fillRect(cx-6,cy-7,12,1);ctx.fillStyle=CT_CHEST_GOLD;ctx.beginPath();ctx.arc(cx,cy-4,1.5,0,Math.PI*2);ctx.fill();if(_tileDetail>=1){var grad=ctx.createRadialGradient(cx,cy-3,2,cx,cy-3,12);grad.addColorStop(0,'rgba(196,149,58,'+pulse+')');grad.addColorStop(0.5,'rgba(196,149,58,'+(pulse*0.2)+')');grad.addColorStop(1,'rgba(196,149,58,0)');ctx.fillStyle=grad;ctx.beginPath();ctx.arc(cx,cy-3,12,0,Math.PI*2);ctx.fill();}else{ctx.fillStyle='rgba(196,149,58,'+(pulse*0.15)+')';ctx.beginPath();ctx.arc(cx,cy-3,8,0,Math.PI*2);ctx.fill();}
if(_tileDetail>=1){var r1=tileRand(col,row,7);var r2=tileRand(col,row,8);var sparkle=Math.sin(t*3+r1*6)*0.5+0.5;if(sparkle>0.6){ctx.fillStyle='rgba(255,215,0,'+(sparkle*0.6)+')';ctx.beginPath();ctx.arc(cx+(r1-0.5)*14,cy-8+(r2-0.5)*6,1,0,Math.PI*2);ctx.fill();}
if(_tileDetail>=2){var sparkle2=Math.sin(t*2.5+r2*4)*0.5+0.5;if(sparkle2>0.65){ctx.fillStyle='rgba(255,215,0,'+(sparkle2*0.5)+')';ctx.beginPath();ctx.arc(cx+(r2-0.5)*12,cy-6+(r1-0.5)*8,0.8,0,Math.PI*2);ctx.fill();}}}}
function drawTileDecoration(ctx,cx,cy,tile,biome,col,row,timestamp){/* reduced scale for map overview */ctx.save();ctx.translate(cx,cy);ctx.scale(0.55,0.55);ctx.translate(-cx,-cy);switch(tile){case'T':drawTreeDecoration(ctx,cx,cy,biome,col,row);break;case'M':drawMountainDecoration(ctx,cx,cy,col,row);break;case'r':drawRockDecoration(ctx,cx,cy,col,row);break;case'w':drawWaterDecoration(ctx,cx,cy,timestamp,false);break;case'W':drawWaterDecoration(ctx,cx,cy,timestamp,true);break;case'L':drawLavaDecoration(ctx,cx,cy,timestamp);break;case'R':drawRuinsDecoration(ctx,cx,cy,col,row);break;case'b':drawBonesDecoration(ctx,cx,cy,col,row,biome);break;case'p':drawPathDecoration(ctx,cx,cy,col,row);break;case'i':drawIceDecoration(ctx,cx,cy,col,row);break;case's':drawSandDecoration(ctx,cx,cy,col,row);break;case'm':drawMudDecoration(ctx,cx,cy,col,row);break;case'v':drawVolcanicDecoration(ctx,cx,cy,col,row);break;case'g':drawGrassDecoration(ctx,cx,cy,col,row,biome);break;case'.':drawGroundTexture(ctx,cx,cy,col,row,biome);break;case'D':drawDoorDecoration(ctx,cx,cy,col,row);break;case'#':drawWallTileDecoration(ctx,cx,cy,col,row,biome);break;case'C':drawChestDecoration(ctx,cx,cy,col,row,timestamp);break;}ctx.restore();}